    """Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl. 1, suppl 5 pr, suppl. 12, suppl. 1-2, suppl. 1
    """
    issue = issue.strip()
    if not issue:
        return None, None

    fields = issue.split()
    for field in fields:
        if field.startswith("25"):
            return "25 suppl", None
        elif "s2" in field:
            return "s2", None
        elif "spe" in field:
            return "spe", None
        elif "-" in field or field.isdigit():
            if "." in field:
                field = field.replace(".", "")
            return field, None

    return None, None

