    merged = {}

    for node in nodes:
        key = node[0].value
        value = node[1]
        if key in merged:
            if isinstance(value, dict):
                if isinstance(merged[key], dict):
                    merged[key] = deep_merge_nodes([checked_item for checked_item in [(key, valueément) for key, valueément in value.items()] if checked_item[1] is not None and checked_item[1] != {}])
