            elif isinstance(value, list):
                if isinstance(merged[key], list):
                    merged[key] = merged[key] + value
                else:
                    merged[key] = value
            else:
                if value is not None:
                    merged[key] = value
        else:
            merged[key] = value

    return [(key, value) for key, value in merged.items()]

